/* Native, event-driven reconstructions. No Flash runtime, polling or animation loop. */
(() => {
 'use strict';
 const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const T=(fr,en,ar)=>({fr,en,ar}[window.GuideI18n?.lang||'fr']);
 const N=v=>Number(String(v).trim().replace(/[٠-٩]/g,c=>'٠١٢٣٤٥٦٧٨٩'.indexOf(c)).replace(/[۰-۹]/g,c=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(c)).replace(/[٫,]/g,'.'));
 const F=(n,unit='')=>Number.isFinite(n)?new Intl.NumberFormat(GuideI18n.lang,{maximumSignificantDigits:5}).format(Math.abs(n)<1e-12?0:n)+(unit?' '+unit:''):'—';
 const registry={
 's0-s013-ohm03-9':'wire','s0-s013-ohm04-10':'resistor','s0-s014-nrj04-14':'energy','s0-s018-tvn01-23':'generator','s0-s018-tvn05-27':'active','s0-s02m-mon72-48':'rlc','s0-s02m-mon82-55':'loads','s0-s02m-mon85-58':'compensation','s0-s02t-tri35-74':'three','s0-s034-trf05-118':'transformer','s0-s052-tmp00-145':'delay','s0-s052-tmp02-147':'rc','s0-s052-tmp03-148':'charge','s0-s052-tmp04-149':'discharge','s0-s054-cnj01-151':'energy','s1-s1110-csl02-214':'solar','s2-s222-app42-322':'pilot','s2-s222-app43-323':'pilot2','s2-s223-prj04-335':'heating','s2-s232-mct00-343':'dc-motor','s2-s233-mat01-344':'ac-motor','s2-s241-pne02-373':'air','s2-s241-pne03-374':'frl','s2-s242-act01-375':'cylinder','s3-s313-lum01-395':'simple','s3-s313-lum02-396':'socket','s3-s313-lum03-397':'double','s3-s313-lum04-398':'two-way','s3-s313-lum05-399':'switched-socket','s3-s313-lum06-400':'latching','s3-s313-lum07-401':'staircase','s3-s343-dmt02-441':'thermal-curve','s3-s343-dmt04-443':'magnetic-curve','s3-s346-rth01-450':'relay-parts','s3-s346-rth06-455':'overload','s3-s352-ccs22-463':'cam','s3-s352-ccs31-464':'contactor','s3-s352-ccs43-470':'relay-wiring','s3-s352-ccs44-471':'central','s3-s352-ccs51-472':'timer','s5-s521-nor03-568':'zones'};
 const replacements=new Set(['cam','contactor']);
 const field=(id,label,value,min=0,max=1e9,step='any')=>`<label class="sim-control"><span>${E(label)}</span><input id="sim-${id}" data-number="${id}" type="text" inputmode="decimal" value="${E(value)}" data-min="${min}" data-max="${max}" autocomplete="off" spellcheck="false"></label>`;
 const range=(id,label,value,min,max,step=1)=>`<label class="sim-control"><span>${E(label)} <output for="sim-${id}" id="sim-value-${id}">${F(value)}</output></span><input id="sim-${id}" data-number="${id}" type="range" value="${value}" min="${min}" max="${max}" data-min="${min}" data-max="${max}" step="${step}"></label>`;
 const select=(id,label,options,value)=>`<label class="sim-control"><span>${E(label)}</span><select id="sim-${id}">${options.map(([v,l])=>`<option value="${E(v)}" ${String(v)===String(value)?'selected':''}>${E(l)}</option>`).join('')}</select></label>`;
 const check=(id,label,value=false)=>`<label class="sim-check"><input id="sim-${id}" type="checkbox" ${value?'checked':''}>${E(label)}</label>`;
 const button=(id,label,extra='')=>`<button type="button" class="button" data-action="${id}" ${extra}>${E(label)}</button>`;
 const metrics=items=>`<dl class="sim-metrics">${items.map(([label,value,unit])=>`<div><dt>${E(label)}</dt><dd dir="auto">${typeof value==='number'?F(value,unit):E(value)}</dd></div>`).join('')}</dl>`;
 const svg=(body,label,height=250)=>`<svg class="sim-diagram" role="img" aria-label="${E(label)}" viewBox="0 0 520 ${height}" xmlns="http://www.w3.org/2000/svg"><g fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${body}</g></svg>`;
 const text=(x,y,s,attrs='')=>`<text x="${x}" y="${y}" text-anchor="middle" ${attrs}>${E(s)}</text>`;
 const formula=s=>`<div class="sim-formula" dir="ltr">${E(s)}</div>`;
 const note=s=>`<p class="sim-note">${E(s)}</p>`;
 const status=s=>`<div class="sim-status" role="status">${E(s)}</div>`;
 function plot(fn,maximum,label,ymax=1,second){const pts=Array.from({length:121},(_,i)=>[45+430*i/120,205-170*fn(maximum*i/120)/ymax]);return svg(`<path class="secondary" d="M45 25V205H475"/>${[0,.25,.5,.75,1].map(v=>`<path class="off" d="M45 ${205-170*v}H475"/>${text(23,210-170*v,F(v*ymax))}`).join('')}<polyline points="${pts.map(p=>p.join(',')).join(' ')}"/>${second?`<polyline class="secondary" stroke-dasharray="5 4" points="${Array.from({length:121},(_,i)=>[45+430*i/120,205-170*second(maximum*i/120)/ymax].join(',')).join(' ')}"/>`:''}${text(45,228,'0')}${text(475,228,F(maximum))}`,label);}
 function circuit(labels,values=[]){return svg(`<path d="M75 80H160M230 80H330M390 80H445V200H75V143M75 97V80"/><circle cx="75" cy="120" r="23"/><path d="M66 120H84M75 111V129"/><rect x="160" y="68" width="70" height="24"/><rect x="330" y="68" width="60" height="24"/>${text(195,53,labels[0]||'R')}${text(360,53,labels[1]||'R')}${text(75,162,labels[2]||'U')}${text(260,180,values.join(' · '))}`,T('Schéma électrique de principe','Electrical principle diagram','مخطط كهربائي توضيحي'));}
 function numeric(ctx,type){const {get,val}=ctx,M=LegacyModels;let controls='',explain='',update;
  if(type==='wire'){
   controls=select('target',T('Grandeur à calculer','Solve for','الكمية المطلوب حسابها'),[['resistance','R (Ω)'],['rho','ρ (Ω·mm²/m)'],['length','L (m)'],['section','S (mm²)']],'resistance')+select('material',T('Matériau à 20 °C','Material at 20 °C','المادة عند 20 °C'),[['cu',T('Cuivre','Copper','النحاس')],['al',T('Aluminium','Aluminium','الألومنيوم')],['custom',T('Personnalisé','Custom','مخصص')]],'cu')+select('units',T('Unités de saisie','Input units','وحدات الإدخال'),[['usual','Ω·mm²/m / mm²'],['si','Ω·m / m²']],'usual')+field('rho','ρ',.0175,.0000000001,100)+field('length','L (m)',100,.000001)+field('section','S',2.5,.000000001)+field('resistance','R (Ω)',.7,.000000001)+field('r20','R₂₀ (Ω)',1,.000001)+field('alpha','α₀ (K⁻¹)',.0043,-.01,.1)+range('theta','θ (°C)',80,-100,300);
   explain=T('La longueur L est celle du conducteur considéré. Pour une boucle aller-retour, additionnez les deux longueurs. ρ et α sont des valeurs pédagogiques approximatives. α₀ est référencé à 0 °C, pas à 20 °C.','L is the length of the conductor being modelled. Add both lengths for a return loop. Material constants are approximate educational values. α₀ is referenced to 0 °C, not 20 °C.','L هو طول الموصل المدروس. في مسار الذهاب والإياب نجمع الطولين. ثوابت المواد قيم تعليمية تقريبية. معامل α₀ مرجعه 0 °C وليس 20 °C.');
   let lastUnits='usual',lastMaterial='cu';update=()=>{const units=val('units'),material=val('material');if(units!==lastUnits){for(const id of ['rho','section'])ctx.q(id).value=N(ctx.q(id).value)*(units==='si'?1e-6:1e6);lastUnits=units;}if(material!==lastMaterial){if(material!=='custom'){ctx.q('rho').value=(material==='cu'?.0175:.028)*(units==='si'?1e-6:1);ctx.q('alpha').value=material==='cu'?.0043:.0045;}lastMaterial=material;}const target=val('target');for(const k of ['rho','length','section','resistance'])ctx.q(k).disabled=k===target;const v={};for(const k of ['rho','length','section','resistance'])v[k]=k===target?0:get(k);const result=M.wire(target,v);ctx.q(target).value=Number(result.toPrecision(8));const temp=M.temperature(get('r20'),get('alpha'),get('theta'));return circuit(['ρ · L / S',T('Conducteur','Conductor','موصل'),'R'],[F(result)])+metrics([[target,result,target==='length'?'m':target==='section'?(units==='si'?'m²':'mm²'):target==='rho'?(units==='si'?'Ω·m':'Ω·mm²/m'):'Ω'],['Rθ',temp,'Ω']])+formula('R = ρ L / S     Rθ = R₂₀ (1 + α₀ θ) / (1 + 20 α₀)');};
  }else if(type==='generator'){
   controls=field('e','E (V)',14,.001,1000)+field('r','r (Ω)',1,0,10000)+range('load',T('Résistance de charge Rh (Ω)','Load resistance Rh (Ω)','مقاومة الحمل Rh (Ω)'),10,0,100,.1);
   explain=T('Générateur réel modélisé par une source idéale E en série avec r. La courbe représente U en fonction de I. Rh = 0 simule uniquement le court-circuit du modèle.','A real generator is modelled as ideal source E in series with r. The curve shows U versus I. Rh = 0 represents a short circuit only in this model.','يُمثّل المولد الحقيقي بمصدر مثالي E ومقاومة داخلية r. يوضح المنحنى تغير U مع I. قيمة Rh = 0 تمثل القصر في النموذج فقط.');
   update=()=>{const e=get('e'),r=get('r'),m=M.generator(e,r,get('load')),imax=r>0?e/r:Math.max(1,m.i*2);return circuit(['r','Rh','E'],['I = '+F(m.i,'A')])+plot(i=>Math.max(0,e-r*i),imax,'U (V) / I (A)',e)+metrics([['I',m.i,'A'],['U',m.u,'V'],[T('Pertes internes','Internal losses','الفقد الداخلي'),m.loss,'W'],[T('Puissance utile','Load power','قدرة الحمل'),m.p,'W']])+formula('I = E / (r + Rh)     U = E − r I');};
  }else if(type==='active'){
   controls=field('e','E (V)',120,0,1000)+field('r','r (Ω)',.5,0,10000)+field('em',"E′ (V)",100,0,1000)+field('rm',"r′ (Ω)",1,0,10000)+field('rho','ρ (Ω·mm²/m)',.0175,.000001,100)+field('length',T('Longueur totale aller-retour (m)','Total return-loop length (m)','الطول الكلي ذهاباً وإياباً (m)'),100,0,1e6)+field('section','S (mm²)',2.5,.001,10000);
   explain=T('Modèle en régime continu établi. E′ représente la force contre-électromotrice du récepteur actif. Une intensité négative indique que le sens réel du courant est opposé au sens choisi.','Steady DC model. E′ is the active receiver back EMF. A negative current means the actual current direction is opposite to the chosen reference.','نموذج تيار مستمر في الحالة المستقرة. تمثل E′ القوة المحركة الكهربائية العكسية للمستقبِل الفعّال. التيار السالب يعني أن اتجاهه الفعلي معاكس للاتجاه المرجعي.');
   update=()=>{const m=M.active(...['e','r','em','rm','rho','length','section'].map(get));return circuit(['r + Rligne',"E′ + r′ I",'E'],['I = '+F(m.i,'A')])+metrics([['I',m.i,'A'],['Rligne',m.rl,'Ω'],['Ug',m.ug,'V'],['Um',m.um,'V'],['ΔUligne',m.lineDrop,'V'],['r I',m.sourceDrop,'V']])+formula("I = (E − E′) / (r + Rligne + r′)");};
  }else if(type==='rlc'){
   controls=field('u','Ueff (V)',24,0,10000)+field('f','f (Hz)',50,.001,1e6)+field('r','R (Ω)',100,0,1e8)+field('l','L (mH)',200,0,1e8)+field('c','C (µF)',100,0,1e8);
   explain=T('Circuit RLC série idéal en régime sinusoïdal établi. Comme dans le simulateur original, L = 0 ou C = 0 retire le composant. À la résonance sans résistance, le modèle idéal n’a pas de solution finie.','Ideal series RLC in sinusoidal steady state. As in the original simulator, L = 0 or C = 0 removes that component. At resonance with zero resistance, the ideal model has no finite solution.','دارة RLC متسلسلة مثالية في الحالة الجيبية المستقرة. كما في الأصل، تعني L = 0 أو C = 0 حذف العنصر. عند الرنين دون مقاومة لا يملك النموذج المثالي حلاً محدوداً.');
   update=()=>{const m=M.rlc(get('u'),get('f'),get('r'),get('l')/1000,get('c')/1e6),scale=90/Math.max(1,m.ur,m.ul,m.uc);return svg(`<path class="secondary" d="M70 125H470M260 30V225"/><path d="M80 125H${80+m.ur*scale}L${80+m.ur*scale} ${125-(m.ul-m.uc)*scale}"/><circle cx="${80+m.ur*scale}" cy="${125-(m.ul-m.uc)*scale}" r="4" class="active-fill"/>${text(260,245,'UR →    UL − UC ↑')}`,T('Diagramme de Fresnel','Phasor diagram','مخطط المتجهات'))+metrics([['Z',m.z,'Ω'],['Ieff',m.i,'A'],['XL',m.xl,'Ω'],['XC',m.xc,'Ω'],['UR',m.ur,'V'],['UL',m.ul,'V'],['UC',m.uc,'V'],['φ',m.phi,'°'],['P',m.p,'W'],['Q',m.q,'var'],['S',m.s,'VA'],['cos φ',m.pf,'']])+formula('Z = √(R² + (ωL − 1/ωC)²)     I = U / Z');};
  }else if(['loads','compensation','three'].includes(type)){
   const three=type==='three',comp=type!=='loads';controls=field('u',three?'Uligne (V)':'U (V)',three?400:240,.001,1e6)+field('f','f (Hz)',50,.01,1e6)+(comp?field('target','cos φ₂',Math.sqrt(1/1.16),.01,1):'')+(three?select('coupling',T('Couplage des condensateurs','Capacitor connection','توصيل المكثفات'),[['delta','Δ'],['star','Y']],'delta'):'')+note(T('Jusqu’à 8 récepteurs. Une puissance nulle désactive une ligne.','Up to 8 loads. Zero power disables a row.','حتى 8 أحمال. قدرة صفر تلغي الصف.'));
   controls+=`<fieldset><legend>${T('Récepteurs','Loads','الأحمال')}</legend>${Array.from({length:8},(_,i)=>`<details ${i<2?'open':''}><summary>${i+1}</summary>${field('p'+i,'Pu (W)',i<2?1000:0,0,1e9)}${field('eta'+i,'η (%)',100,.01,100)}${field('pf'+i,'cos φ',i<2?.8:1,.01,1)}</details>`).join('')}</fieldset>`;
   explain=T('Bilan des puissances, charges inductives sinusoïdales. Pu est la puissance utile et P = Pu / η. En triphasé, Pu désigne la puissance totale de chaque récepteur équilibré. C est la capacité de chaque condensateur, pas la somme des trois.','Power balance for sinusoidal inductive loads. Pu is useful output power and P = Pu / η. In three phase, Pu is each balanced load’s total power. C is the capacitance of each capacitor, not the sum of the three.','موازنة قدرة لأحمال حثية جيبية. Pu هي القدرة المفيدة وP = Pu / η. في النظام الثلاثي Pu قدرة الحمل المتوازن الإجمالية. C سعة كل مكثف وليست مجموع المكثفات الثلاثة.');
   update=()=>{const m=M.boucherot(Array.from({length:8},(_,i)=>({useful:get('p'+i),efficiency:get('eta'+i),pf:get('pf'+i)})),get('u'),get('f'),comp?get('target'):1,three,three?val('coupling'):'delta',comp);const scale=160/Math.max(1,m.p,m.q);return svg(`<path d="M80 205H${80+m.p*scale}L${80+m.p*scale} ${205-m.q*scale}Z"/><path class="secondary" stroke-dasharray="5 4" d="M80 205L${80+m.p*scale} ${205-m.afterQ*scale}"/>${text(260,232,'P (W)')}${text(400,65,'Q (var)')}`,T('Triangle des puissances','Power triangle','مثلث القدرات'))+metrics([['P',m.p,'W'],['Q',m.q,'var'],['S',m.s,'VA'],['I',m.i,'A'],['cos φ₁',m.pf,''],...(comp?[['Qc',m.qc,'var'],['C',m.capacitor*1e6,'µF'],['I₂',m.afterI,'A'],['cos φ₂',m.afterPF,'']]:[])])+formula('P = Σ(Pu / η)     Q = Σ(P tan φ)     S = √(P² + Q²)');};
  }else if(type==='transformer'){
   controls=select('target',T('Grandeur à calculer','Solve for','الكمية المطلوب حسابها'),[['u2','U₂'],['u1','U₁'],['n1','N₁'],['n2','N₂']],'u2')+field('u1','U₁ (V)',230,.000001)+field('u2','U₂ (V)',23,.000001)+field('n1','N₁',1000,.000001)+field('n2','N₂',100,.000001);
   explain=T('Transformateur idéal, tensions efficaces sinusoïdales. Les pertes, la saturation et la chute de tension en charge sont négligées. Le nombre de spires calculé peut être non entier dans ce modèle de rapport.','Ideal transformer with sinusoidal RMS voltages. Losses, saturation and loaded voltage drop are ignored. The calculated turn count may be fractional in this ratio model.','محوّل مثالي بجهود جيبية فعّالة. تُهمل الفواقد والتشبع وهبوط الجهد مع الحمل. قد يكون عدد اللفات المحسوب كسرياً في نموذج النسبة.');
   update=()=>{const target=val('target'),v={};for(const k of ['u1','u2','n1','n2']){ctx.q(k).disabled=k===target;v[k]=k===target?0:get(k);}v[target]=M.transformer(target,v);ctx.q(target).value=Number(v[target].toPrecision(8));return svg(`<path d="M100 65H200V80${Array.from({length:5},()=> 'q30 12 0 24').join('')}V215H100M420 65H320V80${Array.from({length:5},()=> 'q-30 12 0 24').join('')}V215H420M250 55V225M270 55V225"/>${text(140,140,'U₁')}${text(380,140,'U₂')}${text(210,38,'N₁')}${text(310,38,'N₂')}`,T('Transformateur idéal','Ideal transformer','محوّل مثالي'))+metrics([['U₁',v.u1,'V'],['U₂',v.u2,'V'],['N₁',v.n1,''],['N₂',v.n2,''],['m = N₂ / N₁',v.n2/v.n1,'']])+formula('U₂ / U₁ = N₂ / N₁');};
  }
  return {controls,explain,update};
 }
 function resistor(ctx){const names=[T('Noir','Black','أسود'),T('Brun','Brown','بني'),T('Rouge','Red','أحمر'),T('Orange','Orange','برتقالي'),T('Jaune','Yellow','أصفر'),T('Vert','Green','أخضر'),T('Bleu','Blue','أزرق'),T('Violet','Violet','بنفسجي'),T('Gris','Grey','رمادي'),T('Blanc','White','أبيض')],colors=['#161616','#744026','#d33237','#ee861b','#efcf35','#357f49','#2265be','#844fa1','#92989b','#f5f5ed'],tols=[[1,1],[2,2],[.5,5],[.25,6],[.1,7],[.05,8],[5,-1],[10,-2]],color=n=>n===-1?'#b59b49':n===-2?'#a6adb0':colors[n],name=n=>n===-1?T('Or','Gold','ذهبي'):n===-2?T('Argent','Silver','فضي'):names[n];
  const controls=select('d1',T('Premier chiffre','First digit','الرقم الأول'),names.slice(1).map((n,i)=>[i+1,`${i+1} · ${n}`]),4)+select('d2',T('Deuxième chiffre','Second digit','الرقم الثاني'),names.map((n,i)=>[i,`${i} · ${n}`]),7)+select('mul',T('Multiplicateur','Multiplier','المضاعف'),Array.from({length:12},(_,i)=>[i-2,`10^${i-2} · ${name(i-2)}`]),2)+select('tol',T('Tolérance','Tolerance','التفاوت'),tols.map(([n,c])=>[n,`±${n}% · ${name(c)}`]),5)+`<fieldset><legend>${T('Valeur → couleurs','Value → colours','القيمة ← الألوان')}</legend>${field('encoded','R (Ω)',4700,.1,99e9)}${button('encode',T('Afficher les couleurs','Show bands','عرض الحلقات'))}</fieldset>`;
  return {controls,explain:T('Résistance à quatre bandes, deux chiffres significatifs. Les couleurs des bandes représentent le code physique normalisé ; la couleur seule n’est jamais nécessaire pour lire le résultat.','Four-band resistor with two significant digits. Band colours represent the physical resistor code; every colour is also named and numbered.','مقاومة بأربع حلقات ورقمين معنويين. ألوان الحلقات تمثل الترميز الفيزيائي للمقاومة؛ لكل لون اسم وقيمة رقمية أيضاً.'),action:a=>{if(a!=='encode')return;const value=ctx.get('encoded');let mul=Math.floor(Math.log10(value))-1,digits=value/10**mul;if(mul< -2||mul>9||Math.abs(digits-Math.round(digits))>1e-6)throw Error('two digits');digits=Math.round(digits);ctx.q('d1').value=String(Math.floor(digits/10));ctx.q('d2').value=String(digits%10);ctx.q('mul').value=String(mul);},update:()=>{const a=N(ctx.val('d1')),b=N(ctx.val('d2')),m=N(ctx.val('mul')),tol=N(ctx.val('tol')),r=LegacyModels.resistor(a,b,m,tol),bands=[a,b,m,tols.find(x=>x[0]===tol)[1]];return svg(`<path d="M35 120H140M380 120H485"/><rect x="140" y="80" width="240" height="80" rx="20" fill="var(--elevated)"/>${bands.map((c,i)=>`<rect x="${165+i*53}" y="81" width="18" height="78" fill="${color(c)}" stroke="var(--secondary)"/>${text(174+i*53,190,name(c))}`).join('')}${text(260,225,F(r.value,'Ω'))}`,T('Résistance à quatre bandes','Four-band resistor','مقاومة بأربع حلقات'))+metrics([['R',r.value,'Ω'],[T('Tolérance','Tolerance','التفاوت'),`±${F(tol)}%`],[T('Minimum','Minimum','القيمة الدنيا'),r.min,'Ω'],[T('Maximum','Maximum','القيمة العليا'),r.max,'Ω']]);}};
 }
 function rc(ctx,type){const normal=type==='rc',discharge=type==='discharge';return {controls:(normal?select('mode',T('Régime','Mode','الحالة'),[['charge',T('Charge','Charge','شحن')],['discharge',T('Décharge','Discharge','تفريغ')]],'charge')+field('u','Ua (V)',12,.001,10000)+field('r','R (kΩ)',10,.000001,1e6)+field('c','C (µF)',100,.000001,1e6):'')+range('time','t / τ',1,0,7,.05)+`<div class="sim-actions">${button('rc-reset',T('Revenir à t = 0','Return to t = 0','العودة إلى t = 0'))}${button('rc-step','+ 0.25 τ')}</div>`,explain:T('Source idéale, condensateur initialement déchargé à la charge, chargé à Ua à la décharge. τ = R × C. Le temps est avancé à la demande, sans animation permanente.','Ideal source. The capacitor starts discharged for charging and charged to Ua for discharging. τ = R × C. Advance time manually; no continuous animation.','مصدر مثالي. يبدأ المكثف فارغاً عند الشحن ومشحوناً إلى Ua عند التفريغ. τ = R × C. يتحرك الزمن عند الطلب دون رسوم مستمرة.'),action:a=>{if(a==='rc-reset')ctx.q('time').value=0;if(a==='rc-step')ctx.q('time').value=Math.min(7,ctx.get('time')+.25);},update:()=>{const u=normal?ctx.get('u'):1,r=normal?ctx.get('r')*1000:1,c=normal?ctx.get('c')/1e6:1,d=normal?ctx.val('mode')==='discharge':discharge,time=ctx.get('time'),m=ElectroModels.rc(u,r,c,time*r*c,d);return plot(x=>d?Math.exp(-x):1-Math.exp(-x),7,'Uc / Ua · t / τ')+metrics([['t / τ',time,''],[normal?'τ':'Uc / Ua',normal?m.tau:m.v,normal?'s':''],...(normal?[['Uc',m.v,'V'],['i',m.i*1000,'mA'],['t',time*m.tau,'s']]:[])])+formula(d?'Uc(t) = Ua exp(−t / τ)':'Uc(t) = Ua (1 − exp(−t / τ))');}};
 }
 function delay(ctx){let elapsed=0,last=false,armed=false,lastMode='on';return {controls:select('mode',T('Type de temporisation','Timer type','نوع التأخير'),[['on',T('Retard à l’enclenchement','On delay','تأخير التشغيل')],['off',T('Retard au déclenchement','Off delay','تأخير الفصل')]],'on')+field('delay',T('Durée (s)','Delay (s)','مدة التأخير (s)'),5,0,3600)+check('command',T('Commande d’entrée','Input command','إشارة الإدخال'))+`<div class="sim-actions">${button('tick','+ 1 s')}${button('finish',T('Avancer de la durée réglée','Advance by the set delay','تقديم الزمن بمقدار التأخير'))}${button('zero',T('Réinitialiser','Reset','إعادة الضبط'))}</div>`,explain:T('Le retard à l’enclenchement exige une commande maintenue. Le retard au déclenchement maintient la sortie après la disparition de la commande. Les secondes sont simulées avec les boutons.','On delay requires the input to remain on. Off delay holds the output after the input disappears. Use the buttons to advance simulated seconds.','يتطلب تأخير التشغيل استمرار إشارة الإدخال. يبقي تأخير الفصل الخرج فعالاً بعد زوال الإدخال. تُقدّم الثواني الافتراضية بالأزرار.'),action:a=>{if(a==='zero'){elapsed=0;armed=false;last=false;ctx.q('command').checked=false;}if(a==='tick')elapsed+=1;if(a==='finish')elapsed+=ctx.get('delay');},update:()=>{const input=ctx.q('command').checked,mode=ctx.val('mode'),d=ctx.get('delay');if(mode!==lastMode){elapsed=0;armed=input;lastMode=mode;}if(input!==last){elapsed=0;if(input)armed=true;last=input;}const output=mode==='on'?input&&elapsed>=d:input||(armed&&elapsed<d);return svg(`<path class="secondary" d="M70 75H450M70 170H450"/><rect x="80" y="${input?40:74}" width="145" height="${input?35:1}"/><rect x="280" y="${output?135:169}" width="145" height="${output?35:1}"/>${text(150,110,'IN = '+Number(input))}${text(350,215,'OUT = '+Number(output))}`,T('État logique du temporisateur','Timer logic state','الحالة المنطقية للمؤقت'))+metrics([['t',elapsed,'s'],['OUT',output?'1':'0']])+status(output?T('Sortie active','Output on','الخرج فعّال'):T('Sortie inactive','Output off','الخرج غير فعّال'));}};}
 function lighting(ctx,type){let memory=[false,false,false],remaining=0;const dual=type==='double',two=['two-way','switched-socket'].includes(type),pulse=['latching','relay-wiring','central'].includes(type),timer=['staircase','timer'].includes(type),socket=['socket','switched-socket'].includes(type);const on=T('Allumé','On','مضاء'),off=T('Éteint','Off','مطفأ');
  let controls=check('supply',T('Alimentation du modèle','Model supply','تغذية النموذج'),true);if(!pulse&&!timer&&type!=='socket')controls+=check('a',T('Interrupteur A','Switch A','المفتاح A'))+(dual||two?check('b',T('Interrupteur B','Switch B','المفتاح B')):'');if(type==='switched-socket')controls+=select('locations',T('Points de commande','Control locations','نقاط التحكم'),[['1','1'],['2','2']],'2');
  if(pulse)controls+=`<div class="sim-actions">${button('push0',T('Poussoir A','Push button A','زر الضغط A'))}${button(type==='central'?'push1':'push0',T('Poussoir B','Push button B','زر الضغط B'))}${type==='central'?button('push2',T('Poussoir C','Push button C','زر الضغط C'))+button('all-on',T('Tout allumer','All on','تشغيل الكل'))+button('all-off',T('Tout éteindre','All off','إطفاء الكل')):''}</div>`;
  if(type==='relay-wiring')controls+=select('wires',T('Montage historique','Historical circuit','التركيب التاريخي'),[['4',T('4 fils : poussoir côté phase','4 wires: phase-side push button','4 أسلاك: زر على جهة الطور')],['3',T('3 fils : poussoir côté neutre','3 wires: neutral-side push button','3 أسلاك: زر على جهة المحايد')]],'4');
  if(timer)controls+=field('delay',T('Durée simulée (s)','Simulated duration (s)','المدة الافتراضية (s)'),60,1,3600)+(type==='timer'?check('forced',T('Marche forcée','Forced on','تشغيل دائم')):'')+`<div class="sim-actions">${button('push',T('Appuyer sur le poussoir','Press push button','ضغط الزر'))}${button('tick','+ 1 s')}${button('tick10','+ 10 s')}${button('expire',T('Fin de temporisation','End delay','نهاية المدة'))}</div>`;
  const lamp=(x,y,lit,label)=>`<g class="${lit?'':'off'}"><circle cx="${x}" cy="${y}" r="20" class="${lit?'active-fill':''}"/><path d="M${x-14} ${y-14}l28 28m0-28l-28 28"/></g>${text(x,y+42,label+' · '+(lit?on:off))}`;
  const switchPath=(x,y,closed)=>`<circle cx="${x}" cy="${y}" r="2"/><circle cx="${x+45}" cy="${y}" r="2"/><path d="M${x} ${y}L${x+45} ${closed?y:y-20}"/>`;
  return {controls,explain:type==='relay-wiring'?T('Deux montages historiques, même mémoire bistable. La variante 3 fils est présentée pour comprendre l’archive ; le choix d’un raccordement réel dépend du dispositif et de sa notice.','Two historical circuits share the same bistable memory. The 3-wire variant explains the archive; actual connections depend on the device and its instructions.','تركيبان تاريخيان بالذاكرة ثنائية الاستقرار نفسها. يعرض تركيب 3 أسلاك لفهم الأرشيف؛ التوصيل الفعلي يحدده الجهاز وتعليماته.'):T('Schéma de principe pédagogique. Les commandes modifient l’état du circuit ; les protections, sections et raccordements d’une installation réelle ne sont pas dimensionnés ici.','Educational principle diagram. Controls change circuit states; this is not a design for real installation protection, conductor sizes or connections.','مخطط تعليمي للمبدأ. تغير أدوات التحكم حالة الدارة؛ لا يحسب النموذج حمايات أو مقاطع أو توصيلات منشأة فعلية.'),action:a=>{if(!ctx.q('supply').checked)return;if(a.startsWith('push')&&pulse){const i=Number(a.slice(4));memory[i]=!memory[i];}if(a==='all-on')memory=[true,true,true];if(a==='all-off')memory=[false,false,false];if(timer){if(a==='push'&&!ctx.q('forced')?.checked)remaining=ctx.get('delay');if(a==='tick')remaining=Math.max(0,remaining-1);if(a==='tick10')remaining=Math.max(0,remaining-10);if(a==='expire')remaining=0;}},update:()=>{const supply=ctx.q('supply').checked,a=!!ctx.q('a')?.checked,b=!!ctx.q('b')?.checked;if(!supply)remaining=0;const states=type==='central'?memory:timer?[remaining>0||!!ctx.q('forced')?.checked]:pulse?[memory[0]]:type==='socket'?[true]:LegacyModels.lighting(two&&(type!=='switched-socket'||ctx.val('locations')==='2')?'two-way':dual?'double':'simple',a,b);const lit=states.map(v=>v&&supply);let drawing='';
   if(two&&(type!=='switched-socket'||ctx.val('locations')==='2')){
    drawing=`<path class="secondary" d="M40 60H130M210 35H310M210 95H310M380 60H450V130M450 170V205H40"/><path d="M130 60L210 ${a?95:35}M310 ${b?95:35}L380 60"/>${[[130,60],[210,35],[210,95],[310,35],[310,95],[380,60]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3"/>`).join('')}${socket?`<circle cx="450" cy="150" r="20" class="${lit[0]?'active-fill':'off'}"/><path d="M443 145v7m14-7v7M450 174V230H40"/>${text(450,120,'2P+T')}${text(25,235,'PE')}`:lamp(450,150,lit[0],'H1')}${text(160,125,'A')}${text(345,125,'B')}`;
   }else if(socket){drawing=`<path d="M45 50H165M210 50H395V115M45 190H425V125"/>${type==='socket'?'<path d="M165 50H210"/>':switchPath(165,50,a)}<circle cx="410" cy="120" r="43" class="${lit[0]?'active-fill':'off'}"/><circle cx="395" cy="120" r="5"/><circle cx="425" cy="120" r="5"/><path class="secondary" d="M410 150V225H45M400 150H420M404 155H416"/>${text(410,65,'2P + T')}${text(24,228,'PE')}`;
   }else {drawing=`<path class="secondary" d="M40 45H480M40 200H480"/>${lit.map((v,i)=>{const x=lit.length===1?330:140+i*130,closed=pulse||timer?v:i===0?a:b;return `<path d="M${x} 45V80M${x} 115V135M${x} 175V200M${x} 80L${closed?x:x-22} 115"/><circle cx="${x}" cy="80" r="2"/><circle cx="${x}" cy="115" r="2"/>${lamp(x,155,v,'H'+(i+1))}`;}).join('')}`;if(pulse||timer)drawing+=`<rect x="40" y="90" width="58" height="46"/>${text(69,118,timer?'KT':'K')}<path class="secondary" stroke-dasharray="4 4" d="M98 112H${lit.length===1?310:120}"/>${text(95,237,type==='relay-wiring'?'BP → '+(ctx.val('wires')==='4'?'L':'N'):'BP → K')}`;}
   return svg(`${text(23,50,'L')}${text(23,205,'N')}${drawing}`,T('Schéma et état de la commande','Circuit and control state','مخطط الدارة وحالة التحكم'))+metrics(lit.map((v,i)=>[socket?T('Prise alimentée','Socket powered','المأخذ مغذى'):'H'+(i+1),v?on:off]))+(timer?metrics([[T('Temps restant','Time remaining','الزمن المتبقي'),remaining,'s']]):'')+status(supply?T('Alimentation présente dans le modèle','Model supply present','التغذية موجودة في النموذج'):T('Alimentation coupée dans le modèle','Model supply off','التغذية مفصولة في النموذج'));}};
 }
 function energy(ctx){const forms=[T('Chimique','Chemical','كيميائية'),T('Mécanique','Mechanical','ميكانيكية'),T('Thermique','Thermal','حرارية'),T('Électrique','Electrical','كهربائية')],examples=[
 [0,2,T('Combustion','Combustion','احتراق'),T('L’énergie chimique du combustible est convertie en chaleur.','The fuel’s chemical energy is converted into heat.','تتحول الطاقة الكيميائية للوقود إلى حرارة.')],
 [0,3,T('Pile / accumulateur','Cell / battery','خلية / بطارية'),T('Une réaction électrochimique fournit de l’énergie électrique.','An electrochemical reaction supplies electrical energy.','يوفّر تفاعل كهروكيميائي طاقة كهربائية.')],
 [1,1,T('Boîte de vitesses','Gearbox','علبة تروس'),T('Le mécanisme adapte vitesse et couple ; des pertes subsistent.','The mechanism adapts speed and torque, with some losses.','تكيّف الآلية السرعة وعزم الدوران مع وجود فواقد.')],
 [1,2,T('Frottement','Friction','احتكاك'),T('Le frottement transforme une partie de l’énergie mécanique en chaleur.','Friction converts some mechanical energy into heat.','يحوّل الاحتكاك جزءاً من الطاقة الميكانيكية إلى حرارة.')],
 [1,3,T('Générateur tournant','Rotating generator','مولد دوّار'),T('Une machine entraînée mécaniquement produit de l’énergie électrique.','A mechanically driven machine produces electrical energy.','تنتج آلة مدفوعة ميكانيكياً طاقة كهربائية.')],
 [2,0,T('Réaction endothermique','Endothermic reaction','تفاعل ماص للحرارة'),T('La transformation chimique absorbe de la chaleur.','The chemical process absorbs heat.','تمتص العملية الكيميائية حرارة.')],
 [2,1,T('Moteur thermique','Heat engine','محرك حراري'),T('Une partie de la chaleur reçue devient du travail mécanique ; le reste est rejeté.','Some supplied heat becomes mechanical work; the remainder is rejected.','يتحول جزء من الحرارة المقدمة إلى شغل ميكانيكي ويُطرح الباقي.')],
 [2,2,T('Échangeur','Heat exchanger','مبادل حراري'),T('La chaleur passe entre deux milieux à des températures différentes.','Heat transfers between media at different temperatures.','تنتقل الحرارة بين وسطين بدرجتي حرارة مختلفتين.')],
 [2,3,T('Thermocouple','Thermocouple','مزدوج حراري'),T('Une différence de température entre jonctions produit une tension thermoélectrique.','A temperature difference between junctions produces a thermoelectric voltage.','يولد اختلاف الحرارة بين الوصلات جهداً كهروحرارياً.')],
 [3,0,T('Électrolyse','Electrolysis','تحليل كهربائي'),T('Une source électrique permet une transformation chimique.','An electrical source drives a chemical transformation.','يدفع مصدر كهربائي عملية تحول كيميائي.')],
 [3,1,T('Moteur électrique','Electric motor','محرك كهربائي'),T('L’énergie électrique devient de l’énergie mécanique, avec des pertes.','Electrical energy becomes mechanical energy, with losses.','تتحول الطاقة الكهربائية إلى طاقة ميكانيكية مع فواقد.')],
 [3,2,T('Effet Joule','Joule heating','مفعول جول'),T('Un courant dans une résistance dissipe une puissance thermique P = R I².','Current through a resistor dissipates heat at a rate P = R I².','يبدد التيار المار في مقاومة قدرة حرارية P = R I².')],
 [3,3,T('Transformateur','Transformer','محوّل'),T('En alternatif, le transformateur adapte les niveaux de tension et de courant.','In AC, a transformer adapts voltage and current levels.','في التيار المتناوب يكيّف المحوّل مستويات الجهد والتيار.')]];
 let chosen=0;return {controls:note(T('Sélectionnez une conversion. Les flèches indiquent la forme d’entrée puis la forme de sortie.','Select a conversion. Arrows show input then output energy forms.','اختر تحويلاً. يشير السهم إلى طاقة الإدخال ثم طاقة الخرج.'))+`<div class="sim-parts">${examples.map((e,i)=>button('energy'+i,e[2],`aria-pressed="${i===0}"`)).join('')}</div>`,explain:T('Les conversions ne créent pas d’énergie. Le rendement mesure la fraction utile ; les pertes sont souvent dissipées sous forme de chaleur.','Energy conversions do not create energy. Efficiency measures the useful fraction; losses often appear as heat.','لا تنشئ التحويلات طاقة جديدة. يقيس المردود الجزء المفيد، وغالباً ما تتبدد الفواقد كحرارة.'),action:a=>{if(a.startsWith('energy'))chosen=Number(a.slice(6));},update:()=>{const e=examples[chosen];ctx.host.querySelectorAll('[data-action^=energy]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===chosen)));return svg(`<rect x="25" y="55" width="145" height="100" rx="10" class="active-fill"/><rect x="350" y="55" width="145" height="100" rx="10" class="active-fill"/><path d="M185 105H335m-12-8l12 8-12 8"/>${text(98,110,forms[e[0]])}${text(423,110,forms[e[1]])}${text(260,205,e[2])}`,forms[e[0]]+' → '+forms[e[1]])+`<div class="sim-explanation"><h3>${E(e[2])}</h3><p>${E(e[3])}</p></div>`;}};
 }
 function explorer(ctx,type){const item=(fr,en,ar,df,de,da)=>[T(fr,en,ar),T(df,de,da)];let parts=[];
  const motor=type.endsWith('motor');
  if(motor)parts=[
   item('Stator','Stator','العضو الثابت','Partie fixe créant le champ magnétique.','Stationary part producing the magnetic field.','الجزء الثابت الذي ينشئ المجال المغناطيسي.'),
   item('Rotor','Rotor','العضو الدوار','Partie mobile entraînant l’arbre. Dans un moteur asynchrone, le rotor tourne moins vite que le champ en mode moteur.','Moving part driving the shaft. In induction motor operation, the rotor turns slower than the rotating field.','الجزء المتحرك الذي يدير العمود. في عمل المحرك الحثي يدور العضو الدوار أبطأ من المجال الدوار.'),
   item('Arbre et clavette','Shaft and key','العمود والخـابور','Transmettent le couple à la charge mécanique.','Transmit torque to the mechanical load.','ينقلان عزم الدوران إلى الحمل الميكانيكي.'),
   item('Roulements et flasques','Bearings and end shields','المحامل والأغطية الطرفية','Guident la rotation et maintiennent le rotor centré.','Guide rotation and keep the rotor centred.','توجه الدوران وتحافظ على تمركز العضو الدوار.'),
   item('Ventilateur et capot','Fan and cover','المروحة وغطاؤها','Favorisent le refroidissement tout en protégeant les parties mobiles.','Provide cooling while guarding the moving parts.','يساعدان على التبريد مع حماية الأجزاء المتحركة.'),
   item('Boîte à bornes','Terminal box','صندوق الأطراف','Permet les connexions des enroulements selon la plaque signalétique et la notice.','Connects windings according to the nameplate and instructions.','تُوصل فيه الملفات وفق لوحة البيانات وتعليمات الصانع.'),
   type==='dc-motor'?item('Collecteur et balais','Commutator and brushes','المبدّل والفحمات','Dans un moteur à balais, assurent la commutation du courant dans le rotor.','In a brushed motor, switch current through the rotor windings.','في المحرك ذي الفحمات يبدّلان اتجاه التيار في ملفات العضو الدوار.'):item('Plaque signalétique','Nameplate','لوحة البيانات','Indique tensions, couplages, courant, puissance, vitesse et conditions de service.','Lists voltages, connections, current, power, speed and duty conditions.','تحدد الجهود والتوصيلات والتيار والقدرة والسرعة وظروف الخدمة.')];
  else if(type==='solar')parts=[
   item('Modules photovoltaïques','PV modules','الألواح الكهروضوئية','Convertissent une partie du rayonnement solaire en énergie électrique continue.','Convert part of the solar radiation into DC electrical energy.','تحول جزءاً من الإشعاع الشمسي إلى طاقة كهربائية مستمرة.'),
   item('Régulateur de charge','Charge controller','منظم الشحن','Adapte et limite la charge de la batterie selon sa technologie.','Adapts and limits battery charging for its chemistry.','يكيّف شحن البطارية ويحده وفق تقنيتها.'),
   item('Batterie','Battery','البطارية','Stocke l’énergie et alimente le bus continu quand la production est insuffisante.','Stores energy and supplies the DC bus when generation is insufficient.','تخزن الطاقة وتغذي ناقل التيار المستمر عند نقص الإنتاج.'),
   item('Onduleur','Inverter','العاكس','Convertit le courant continu en alternatif adapté aux récepteurs.','Converts DC into AC suitable for the loads.','يحوّل التيار المستمر إلى متناوب مناسب للأحمال.'),
   item('Charges AC','AC loads','أحمال AC','Reçoivent l’énergie à la sortie de l’onduleur.','Receive energy from the inverter output.','تتلقى الطاقة من خرج العاكس.'),
   item('Charges DC','DC loads','أحمال DC','Utilisent le bus continu à une tension compatible.','Use the DC bus at a compatible voltage.','تستخدم ناقل التيار المستمر بجهد متوافق.'),
   item('Groupe électrogène','Generator set','مجموعة توليد','Source de secours mécanique et électrique.','Mechanical and electrical backup source.','مصدر احتياطي ميكانيكي وكهربائي.'),
   item('Redresseur / chargeur','Rectifier / charger','مقوّم / شاحن','Convertit l’alternatif du groupe en continu pour la charge.','Converts the generator AC into DC for charging.','يحوّل متناوب المولد إلى مستمر للشحن.')];
  else if(type==='air'||type==='frl')parts=[
   ...(type==='air'?[
    item('Compresseur et moteur','Compressor and motor','الضاغط والمحرك','Le moteur entraîne le compresseur qui élève la pression de l’air.','The motor drives the compressor to increase air pressure.','يدير المحرك الضاغط لرفع ضغط الهواء.'),
    item('Réservoir','Air receiver','خزان الهواء','Stocke l’air comprimé et réduit les fluctuations de débit.','Stores compressed air and reduces flow fluctuations.','يخزن الهواء المضغوط ويخفف تقلبات التدفق.'),
    item('Pressostat','Pressure switch','مفتاح الضغط','Commande la production entre deux seuils de pression.','Controls production between two pressure thresholds.','يتحكم بالإنتاج بين حدين للضغط.'),
    item('Soupape et purge','Relief valve and drain','صمام الأمان والتصريف','La soupape limite la surpression ; la purge évacue les condensats.','The relief valve limits overpressure; the drain removes condensate.','يحد صمام الأمان من فرط الضغط ويصرف صمام التصريف الماء المتكثف.')]:[]),
   item('Filtre','Filter','المرشح','Retient les particules et sépare une partie des condensats.','Traps particles and separates some condensate.','يحجز الجسيمات ويفصل جزءاً من الماء المتكثف.'),
   item('Régulateur et manomètre','Regulator and gauge','المنظم ومقياس الضغط','Le régulateur ajuste la pression aval ; le manomètre l’indique.','The regulator adjusts downstream pressure; the gauge displays it.','يضبط المنظم ضغط المخرج ويعرضه مقياس الضغط.'),
   item('Lubrificateur','Lubricator','المزيّت','Ajoute un brouillard d’huile seulement si les composants du réseau le nécessitent.','Adds oil mist only when downstream components require it.','يضيف رذاذ زيت فقط إذا كانت مكونات الشبكة تحتاج إليه.')];
  else parts=[
   item('Bilames','Bimetal strips','الصفائح ثنائية المعدن','Le courant chauffe les bilames. Leur déformation actionne le mécanisme de déclenchement.','Current heats the bimetal strips; their deformation operates the trip mechanism.','يسخن التيار الصفائح ثنائية المعدن ويشغّل انحناؤها آلية الفصل.'),
   item('Réglage Ir','Ir setting','ضبط Ir','Se règle d’après le moteur, le montage et la notice, jamais pour masquer une surcharge.','Set according to the motor, circuit and instructions, never to conceal an overload.','يُضبط وفق المحرك والتركيب والتعليمات ولا يُرفع لإخفاء حمل زائد.'),
   item('Contact 95–96','Contact 95–96','التلامس 95–96','Contact normalement fermé, ouvert au déclenchement.','Normally closed contact; opens on a trip.','تلامس مغلق عادة ويفتح عند الفصل.'),
   item('Contact 97–98','Contact 97–98','التلامس 97–98','Contact normalement ouvert, fermé au déclenchement pour la signalisation.','Normally open contact; closes on a trip for indication.','تلامس مفتوح عادة ويغلق عند الفصل للإشارة.'),
   item('Test / arrêt','Test / stop','اختبار / إيقاف','Vérifient ou actionnent la commande du relais selon les fonctions du modèle.','Test or operate the relay control according to the device functions.','يختبران أو يشغّلان التحكم في المرحّل بحسب وظائف الجهاز.'),
   item('Réarmement','Reset','إعادة التسليح','Manuel ou automatique selon l’appareil et son réglage, après disparition de la cause.','Manual or automatic depending on the device and setting, after the cause is removed.','يدوي أو آلي حسب الجهاز وضبطه بعد إزالة السبب.')];
  let selected=0;const controls=`<div class="sim-parts">${parts.map((p,i)=>button('part'+i,`${i+1} · ${p[0]}`,`aria-pressed="${i===0}"`)).join('')}</div>`+(motor?range('separation',T('Vue éclatée','Exploded view','منظور تفكيكي'),0,0,1,.05):'');
  return {controls,explain:T('Sélectionnez un repère pour comprendre sa fonction. Les formes sont schématiques ; les dimensions et positions exactes dépendent du matériel. Les explications historiques complètes restent dans l’onglet Lecture.','Select a numbered part to understand its function. Shapes are schematic; exact dimensions and positions depend on the equipment. Full historical explanations remain in the Reading tab.','اختر جزءاً مرقماً لفهم وظيفته. الأشكال تخطيطية؛ تعتمد الأبعاد والمواضع الفعلية على الجهاز. تبقى الشروحات التاريخية الكاملة في تبويب القراءة.'),action:a=>{if(a.startsWith('part'))selected=Number(a.slice(4));},update:()=>{ctx.host.querySelectorAll('[data-action^=part]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i===selected)));let drawing='';
    if(motor){const gap=ctx.get('separation')*20;drawing=`<g transform="translate(${gap},0)"><rect x="160" y="80" width="160" height="100" rx="16" class="${selected===0?'selected':'part'}"/><path d="M175 90V170M190 85V175M205 85V175M220 85V175M235 85V175M250 85V175M265 85V175M280 85V175M295 90V170"/>${text(240,62,'1')}</g><g transform="translate(${-gap*2},0)"><rect x="105" y="112" width="200" height="36" rx="6" class="${selected===1?'selected':'part'}"/>${text(205,135,'2')}<path class="${selected===2?'selected':''}" d="M45 130H350"/>${text(70,113,'3')}</g><ellipse cx="${135-gap}" cy="130" rx="16" ry="57" class="${selected===3?'selected':'part'}"/>${text(135-gap,212,'4')}<g transform="translate(${gap*2},0)"><circle cx="370" cy="130" r="30" class="${selected===4?'selected':'part'}"/><path d="M350 110l40 40m-40 0l40-40"/>${text(370,190,'5')}</g><rect x="225" y="30" width="65" height="40" class="${selected===5?'selected':'part'}"/>${text(257,55,'6')}<rect x="260" y="187" width="55" height="26" class="${selected===6?'selected':'part'}"/>${text(287,205,'7')}`;}
    else {const positions=type==='solar'?[[65,45],[235,45],[235,125],[405,125],[405,210],[235,210],[65,210],[65,125]]:parts.map((_,i)=>[90+(i%3)*165,55+Math.floor(i/3)*80]);const edges=type==='solar'?[[0,1],[1,2],[2,3],[3,4],[2,5],[6,7],[7,2]]:type==='air'?[[0,1],[1,4],[4,5],[5,6],[2,0],[3,1]]:[[0,1],[1,2]];drawing=edges.map(([a,b])=>`<path class="secondary" d="M${positions[a][0]} ${positions[a][1]}L${positions[b][0]} ${positions[b][1]}"/>`).join('')+positions.map(([x,y],i)=>`<rect x="${x-42}" y="${y-23}" width="84" height="46" rx="${type==='air'&&i===1?20:6}" class="${selected===i?'selected':'part'}"/>${text(x,y+5,String(i+1))}`).join('');}
    return svg(drawing,parts.map((p,i)=>`${i+1}: ${p[0]}`).join('; '),motor?250:285)+`<div class="sim-explanation"><h3>${selected+1} · ${E(parts[selected][0])}</h3><p>${E(parts[selected][1])}</p></div>`;}};
 }
 function cylinder(ctx){let extended=false;return {controls:field('pressure',T('Pression (bar)','Pressure (bar)','الضغط (bar)'),6,0,16)+field('diameter',T('Diamètre du piston (mm)','Piston diameter (mm)','قطر المكبس (mm)'),50,.01,500)+field('rod',T('Diamètre de tige (mm)','Rod diameter (mm)','قطر القضيب (mm)'),20,0,499)+`<div class="sim-actions">${button('extend',T('Sortir la tige','Extend rod','إخراج القضيب'))}${button('retract',T('Rentrer la tige','Retract rod','إرجاع القضيب'))}</div>`,explain:T('Vérin à double effet idéal. La pression alimente une chambre pendant que l’autre est à l’échappement. Forces calculées sans frottement ni contre-pression ; la force de rentrée est plus faible à cause de la tige.','Ideal double-acting cylinder. One chamber is pressurised while the other exhausts. Forces ignore friction and back pressure; retraction force is lower because of the rod area.','أسطوانة مزدوجة الفعل مثالية. تُضغط حجرة بينما تفرّغ الأخرى الهواء. تُحسب القوى دون احتكاك أو ضغط معاكس؛ قوة الرجوع أقل بسبب مساحة القضيب.'),action:a=>{if(a==='extend')extended=true;if(a==='retract')extended=false;},update:()=>{const m=LegacyModels.cylinder(ctx.get('pressure'),ctx.get('diameter'),ctx.get('rod')),x=extended?305:145;return svg(`<rect x="90" y="65" width="270" height="115" rx="8"/><rect x="92" y="67" width="${x-92}" height="111" class="${extended?'active-fill':'part'}"/><rect x="${x+15}" y="67" width="${343-x}" height="111" class="${extended?'part':'active-fill'}"/><rect x="${x}" y="68" width="15" height="109" class="selected"/><rect x="${x+15}" y="114" width="155" height="17" class="part"/><path d="M115 180V210M335 180V210"/>${text(115,235,'A')}${text(335,235,'B')}${text(225,40,T('Piston • tige • chambres A/B','Piston • rod • chambers A/B','مكبس • قضيب • حجرتان A/B'))}`,T('Vérin double effet','Double-acting cylinder','أسطوانة مزدوجة الفعل'))+metrics([[T('Force en sortie','Extension force','قوة الخروج'),m.extension,'N'],[T('Force en rentrée','Retraction force','قوة الرجوع'),m.retraction,'N']])+status(extended?T('A sous pression · B à l’échappement','A pressurised · B exhausting','A مضغوطة · B تفرّغ الهواء'):T('B sous pression · A à l’échappement','B pressurised · A exhausting','B مضغوطة · A تفرّغ الهواء'))+formula('Fsortie = p π D² / 4     Frentrée = p π (D² − d²) / 4');}};
 }
 function pilot(ctx,type){const modes=[['comfort',T('Confort','Comfort','راحة')],['eco',T('Éco','Eco','اقتصادي')],['frost',T('Hors gel','Frost protection','منع التجمد')],['stop',T('Arrêt chauffage','Heating off','إيقاف التدفئة')]],count=type==='pilot2'?2:1;return {controls:Array.from({length:count},(_,i)=>select('zone'+i,T('Zone','Zone','منطقة')+' '+(i+1),modes,'comfort')).join('')+check('supply',T('Alimentation des radiateurs','Heater power supply','تغذية المدافئ'),true)+check('pilot',T('Alimentation du fil pilote','Pilot-wire supply','تغذية سلك التحكم'),true),explain:T('Modèle à quatre ordres. Le fil pilote peut rester sous tension même si l’alimentation du radiateur est coupée. L’ordre Arrêt coupe la chauffe, pas nécessairement les tensions. Les signaux sont représentés sans délai de décodage.','Four-command model. The pilot wire can remain live when heater power is off. The Stop command stops heating, not necessarily voltage. Signals are shown without decoding delay.','نموذج بأربعة أوامر. قد يبقى سلك التحكم تحت الجهد بعد فصل تغذية المدفأة. أمر الإيقاف يوقف التسخين ولا يعني فصل الجهد. تُعرض الإشارات دون تأخير فك الترميز.'),update:()=>Array.from({length:count},(_,i)=>{const supplied=ctx.q('supply').checked,pilotOn=ctx.q('pilot').checked,mode=pilotOn?ctx.val('zone'+i):'comfort';const wave=x=>{const s=Math.sin(x*4*Math.PI);return mode==='comfort'?0:mode==='eco'?s:mode==='stop'?Math.max(0,s):Math.min(0,s);};return `<h3>${T('Zone','Zone','منطقة')} ${i+1}</h3>`+svg(`<path class="secondary" d="M35 120H485"/><polyline points="${Array.from({length:161},(_,j)=>[35+450*j/160,120-70*wave(j/160)].join(',')).join(' ')}"/>${text(260,225,'u / û · t')}`,modes.find(m=>m[0]===mode)[1])+status((supplied?T('Ordre reçu : ','Received command: ','الأمر المستلم: '):T('Radiateur non alimenté · ordre sur le fil : ','Heater unpowered · wire command: ','المدفأة غير مغذاة · أمر السلك: '))+modes.find(m=>m[0]===mode)[1]);}).join('')};}
 function heating(ctx){const controls=field('height',T('Hauteur sous plafond (m)','Ceiling height (m)','ارتفاع السقف (m)'),2.5,.1,3.5)+field('inside',T('Température intérieure (°C)','Indoor temperature (°C)','الحرارة الداخلية (°C)'),20,-20,24)+field('outside',T('Température extérieure (°C)','Outdoor temperature (°C)','الحرارة الخارجية (°C)'),-5,-27,24)+`<fieldset><legend>${T('Dimensions des 10 pièces','Dimensions of 10 rooms','أبعاد 10 غرف')}</legend>${Array.from({length:10},(_,i)=>`<details ${i<2?'open':''}><summary>${T('Pièce','Room','غرفة')} ${i+1}</summary>${field('length'+i,'L (m)',i<2?4:0,0,50)}${field('width'+i,'l (m)',i<2?3:0,0,50)}</details>`).join('')}</fieldset>`;return {controls,explain:T('Méthode historique « option 1 » du guide, conservée pour l’étude. Ce calcul simplifié n’est pas un bilan thermique actuel : il ne décrit ni l’isolation, ni la ventilation, ni les apports. Limites originales : 50 m² par pièce, hauteur 3,5 m, intérieur 24 °C, extérieur −27 °C. Arrondis intermédiaires supprimés pour éviter leur accumulation ; les paliers de chauffage historiques sont conservés.','Historical “option 1” method retained for study. This simplified calculation is not a current heat-loss assessment: it does not model insulation, ventilation or gains. Original limits: 50 m² per room, 3.5 m height, 24 °C indoors and −27 °C outdoors. Intermediate rounding is removed to prevent accumulated error; historical heater steps are retained.','طريقة «الخيار 1» التاريخية محفوظة للدراسة. هذا الحساب المبسط ليس دراسة حرارية حديثة ولا يمثل العزل أو التهوية أو المكاسب الحرارية. حدود الأصل: 50 m² للغرفة وارتفاع 3.5 m وداخل 24 °C وخارج −27 °C. أُلغي التقريب الوسيط لمنع تراكم الخطأ مع إبقاء درجات القدرة التاريخية.'),update:()=>{const m=LegacyModels.heating(Array.from({length:10},(_,i)=>({length:ctx.get('length'+i),width:ctx.get('width'+i)})),ctx.get('height'),ctx.get('inside'),ctx.get('outside'));return formula('P = (10 + 0.8 (Tint − Text)) × V')+metrics([[T('Surface totale','Total area','المساحة الكلية'),m.surface,'m²'],[T('Volume','Volume','الحجم'),m.volume,'m³'],[T('Puissance calculée','Calculated power','القدرة المحسوبة'),m.power,'W'],[T('Palier installé','Installed step','درجة القدرة المركبة'),m.installed,'W']])+`<div class="sim-table-wrap"><table class="sim-table"><thead><tr><th>${T('Pièce','Room','الغرفة')}</th><th>m²</th><th>P (W)</th><th>${T('Palier (W)','Step (W)','الدرجة (W)')}</th></tr></thead><tbody>${m.rows.map((r,i)=>`<tr><th>${i+1}</th><td>${F(r.area)}</td><td>${F(r.power)}</td><td>${F(r.installed)}</td></tr>`).join('')}</tbody></table></div>`+note(T('En dessous de 250 W : aucun convecteur dans ce modèle. À partir de 250 W : palier strictement supérieur, par pas de 250 W, comme dans l’archive.','Below 250 W: no heater in this model. From 250 W: the strictly higher 250 W step, as in the archive.','أقل من 250 W: لا مدفأة في النموذج. ابتداءً من 250 W تُختار الدرجة الأعلى تماماً بخطوات 250 W كما في الأرشيف.'));}};
 }
 function contactDiagram(closed,tripped=false){return svg(`<rect x="35" y="80" width="85" height="65" rx="6" class="${closed?'selected':'part'}"/>${text(77,118,'A1 / A2')}<path class="secondary" stroke-dasharray="4 4" d="M120 112H450"/>${[220,320,420].map((x,i)=>`<path d="M${x} 40V90M${x} 135V205M${x} 90L${closed?x:x-20} 135"/>${text(x,25,'L'+(i+1))}${text(x,228,'T'+(i+1))}`).join('')}${text(77,180,tripped?'TRIP':'K')}`,T('Bobine et contacts liés mécaniquement','Coil and mechanically linked contacts','ملف وتلامسات مرتبطة ميكانيكياً'));}
 function protection(ctx,type){const contactor=type==='contactor';let tripped=false,hot=false,stopped=false;const controls=contactor?check('coil',T('Alimenter la bobine A1–A2','Energise coil A1–A2','تغذية الملف A1–A2')):select('resetmode',T('Réarmement','Reset mode','إعادة التسليح'),[['manual',T('Manuel','Manual','يدوي')],['auto',T('Automatique','Automatic','آلي')]],'manual')+field('ir','Ir (A)',4,1,100)+`<div class="sim-actions">${button('trip',T('Simuler une surcharge','Simulate overload','محاكاة حمل زائد'))}${button('test',T('Test de déclenchement','Trip test','اختبار الفصل'))}${button('cool',T('Défaut supprimé et relais refroidi','Fault cleared and relay cooled','أُزيل العطل وبَرُد المرحّل'))}${button('reset',T('Réarmer','Reset','إعادة التسليح'))}${button('stop',T('Maintenir / relâcher Arrêt','Hold / release Stop','إمساك / تحرير الإيقاف'))}</div>`;
  return {controls,explain:contactor?T('Reconstruction pédagogique : le fichier original est illisible. Une bobine déplace l’armature, ferme les contacts de puissance et modifie les auxiliaires. Un contacteur ne remplace pas une protection contre les surintensités.','Educational reconstruction: the original file is unreadable. The coil moves the armature, closes power contacts and changes auxiliary contacts. A contactor does not replace overcurrent protection.','إعادة بناء تعليمية: الملف الأصلي غير قابل للقراءة. يحرك الملف القلب ويغلق تلامسات القدرة ويغير المساعدة. لا يحل الكونتاكتور محل الحماية من التيار الزائد.'):T('Modèle logique d’un relais thermique. Ir est une indication de réglage, sans courbe de temps de déclenchement calculée. Ne jamais augmenter Ir pour dissimuler un défaut. Le réarmement automatique restaure les contacts ; il ne représente pas une commande de redémarrage du moteur.','Logical thermal-overload relay model. Ir is a setting indicator; no time-to-trip curve is calculated. Never raise Ir to conceal a fault. Automatic reset restores contacts; it does not represent a motor restart command.','نموذج منطقي لمرحّل حراري. Ir بيان ضبط دون حساب منحنى زمن الفصل. لا ترفع Ir لإخفاء عطل. تعيد إعادة التسليح الآلية وضع التلامسات ولا تمثل أمر إعادة تشغيل للمحرك.'),action:a=>{if(a==='trip'){tripped=true;hot=true;}if(a==='test')tripped=true;if(a==='cool')hot=false;if(a==='reset'&&!hot)tripped=false;if(a==='stop')stopped=!stopped;},update:()=>{if(contactor){const closed=ctx.q('coil').checked;return contactDiagram(closed)+metrics([['A1–A2',closed?'1':'0'],['13–14 (NO)',closed?T('Fermé','Closed','مغلق'):T('Ouvert','Open','مفتوح')],['21–22 (NC)',closed?T('Ouvert','Open','مفتوح'):T('Fermé','Closed','مغلق')]])+status(closed?T('Armature attirée','Armature pulled in','القلب منجذب'):T('Retour par ressort','Spring return','عودة بالنابض'));}ctx.get('ir');if(ctx.val('resetmode')==='auto'&&!hot)tripped=false;const nc=!tripped&&!stopped;return svg(`<rect x="60" y="55" width="120" height="135" rx="8" class="${hot?'selected':'part'}"/>${text(120,100,'Ir = '+F(ctx.get('ir'),'A'))}${text(120,150,hot?'I²R':'RT')}<path d="M285 70H340M385 70H445M340 70L385 ${nc?70:45}M285 165H340M385 165H445M340 165L385 ${tripped?165:140}"/>${text(360,102,'95–96')}${text(360,202,'97–98')}`,T('Contacts du relais thermique','Thermal relay contacts','تلامسات المرحّل الحراري'))+metrics([['95–96',nc?T('Fermé','Closed','مغلق'):T('Ouvert','Open','مفتوح')],['97–98',tripped?T('Fermé','Closed','مغلق'):T('Ouvert','Open','مفتوح')]])+status(hot?T('Refroidissement nécessaire avant réarmement','Cooling required before reset','يلزم التبريد قبل إعادة التسليح'):tripped?T('Réarmement manuel requis','Manual reset required','تلزم إعادة التسليح يدوياً'):stopped?T('Bouton Arrêt maintenu','Stop button held','زر الإيقاف ممسوك'):T('Relais prêt','Relay ready','المرحّل جاهز'));}};
 }
 function cam(ctx){let position=0;const table=Array.from({length:12},(_,i)=>i<4?LegacyModels.cam(i):[false,false,false]);return {controls:range('position',T('Position de la came','Cam position','موضع الكامة'),0,0,11)+field('power',T('Puissance de chaque branche (W)','Power of each branch (W)','قدرة كل فرع (W)'),500,0,1e6)+`<fieldset><legend>${T('Contacts de cette position','Contacts at this position','تلامسات هذا الموضع')}</legend>${[0,1,2].map(i=>check('contact'+i,'K'+(i+1))).join('')}</fieldset>`,explain:T('Le fichier de la table d’origine est illisible. Cet atelier de remplacement propose une table modifiable de 12 positions et trois branches de chauffage indépendantes en parallèle. Les positions 0 à 3 illustrent une progression ; les suivantes sont initialement ouvertes. Ce n’est pas le câblage original.','The original switching-table file is unreadable. This replacement workshop provides an editable 12-position table and three independent parallel heater branches. Positions 0–3 demonstrate a progression; later positions start open. This is not the original wiring.','ملف جدول التوصيل الأصلي غير قابل للقراءة. تقدم هذه الورشة البديلة جدولاً قابلاً للتعديل من 12 موضعاً وثلاثة فروع تدفئة مستقلة على التوازي. تعرض المواضع 0 إلى 3 تدرجاً والباقي مفتوح أولاً. هذا ليس التوصيل الأصلي.'),change:el=>{if(el.id.startsWith('sim-contact'))table[position][Number(el.id.slice(-1))]=el.checked;},update:()=>{position=ctx.get('position');const contacts=table[position];contacts.forEach((v,i)=>ctx.q('contact'+i).checked=v);return svg(`<path class="secondary" d="M40 40H480M40 215H480"/>${contacts.map((v,i)=>{const x=120+i*140;return `<path d="M${x} 40V80M${x} 115V145M${x} 180V215M${x} 80L${v?x:x-22} 115"/><rect x="${x-12}" y="145" width="24" height="35" class="${v?'selected':'part'}"/>${text(x+35,103,'K'+(i+1))}`;}).join('')}`,T('Trois branches de chauffage','Three heater branches','ثلاثة فروع تدفئة'))+metrics([[T('Puissance totale','Total power','القدرة الكلية'),contacts.filter(Boolean).length*ctx.get('power'),'W']])+`<div class="sim-table-wrap"><table class="sim-table"><thead><tr><th>${T('Position','Position','الموضع')}</th><th>K1</th><th>K2</th><th>K3</th></tr></thead><tbody>${table.map((row,i)=>`<tr ${i===position?'class="sim-status"':''}><th>${i}</th>${row.map(v=>`<td>${v?'1':'0'}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}};
 }
 function curves(ctx,type){return {controls:range('current',T('Courant : échelle logarithmique','Current: logarithmic scale','التيار: مقياس لوغاريتمي'),1,0,3,.01)+range('seconds',T('Temps : échelle logarithmique','Time: logarithmic scale','الزمن: مقياس لوغاريتمي'),1,-3,4,.01),explain:T('Courbes vectorielles récupérées du dessin original, pour apprendre à lire un graphique logarithmique. Les deux curseurs sont indépendants : le temps affiché est un repère choisi, pas un temps de déclenchement calculé. Ces courbes historiques ne remplacent pas celles du fabricant du dispositif utilisé.','Vector curves recovered from the original drawing for learning logarithmic graph reading. The two cursors are independent: displayed time is a selected coordinate, not a calculated trip time. These historical curves do not replace the actual device manufacturer’s curves.','منحنيات متجهة مستعادة من الرسم الأصلي لتعلّم قراءة المخطط اللوغاريتمي. المؤشران مستقلان: الزمن المعروض إحداثي تختاره وليس زمن فصل محسوباً. لا تحل هذه المنحنيات التاريخية محل منحنيات صانع الجهاز المستخدم.'),update:()=>{const lx=ctx.get('current'),ly=ctx.get('seconds'),curve=window.LegacyCurves[type];return svg(`<path class="secondary" d="M60 45V305H485"/>${Array.from({length:8},(_,i)=>`<path class="off" d="M60 ${305-i*260/7}H485"/>${text(27,310-i*260/7,String(10**(i-3)))}`).join('')}${[0,1,2,3].map(i=>`<path class="off" d="M${60+i*425/3} 45V305"/>${text(60+i*425/3,325,String(10**i))}`).join('')}<g transform="translate(60 45) scale(0.6746031746 0.589569161) translate(-75 -109)"><g transform="${E(curve.transform)}">${curve.paths.map((d,i)=>`<path d="${E(d)}" stroke-width="1.6" ${i%3===1?'stroke-dasharray="6 2"':i%3===2?'stroke-dasharray="2 2"':''}/>`).join('')}</g></g><path stroke="var(--secondary)" stroke-width="1" d="M${60+lx*425/3} 45V305M60 ${305-(ly+3)*260/7}H485"/><circle cx="${60+lx*425/3}" cy="${305-(ly+3)*260/7}" r="4" class="selected"/>${text(260,350,'I (A)')}${text(27,25,'t (s)')}${[6,10,16,20,25,32,40].map(i=>text(60+Math.log10(i)*425/3,34,String(i),`font-size="9"`)).join('')}`,T('Courbes historiques et repères de lecture','Historical curves and reading cursors','منحنيات تاريخية ومؤشرات القراءة'),365)+metrics([['I',10**lx,'A'],['t',10**ly,'s']])+note(T('Calibres des courbes : 6, 10, 16, 20, 25, 32 et 40 A.','Curve ratings: 6, 10, 16, 20, 25, 32 and 40 A.','عيارات المنحنيات: 6 و10 و16 و20 و25 و32 و40 A.'));}};
 }
 function zones(ctx){let selected=1;const descriptions=[
  T('Zone 1 historique : environnement des ouvrages électriques. L’accès aux locaux réservés reste soumis à des conditions, même en dehors du voisinage.','Historical zone 1: electrical installation environment. Access to restricted electrical rooms still has conditions outside the proximity zone.','المنطقة التاريخية 1: محيط المنشآت الكهربائية. يبقى دخول الأماكن الكهربائية المخصصة خاضعاً لشروط حتى خارج منطقة الجوار.'),
  T('Zone 2 historique : voisinage en haute tension, entre les limites définies dans l’ancien document. Les limites et prescriptions actuelles doivent être vérifiées dans le référentiel applicable.','Historical zone 2: high-voltage proximity between the boundaries in the old document. Current boundaries and requirements must be checked in the applicable reference.','المنطقة التاريخية 2: جوار الجهد العالي بين حدود الوثيقة القديمة. يجب التحقق من الحدود والمتطلبات الحالية في المرجع المعمول به.'),
  T('Zone 3 historique : proximité immédiate d’une pièce nue sous tension HT. Il ne s’agit jamais d’une autorisation d’approche pour un débutant.','Historical zone 3: immediate proximity of an exposed live HV part. This is never permission for a beginner to approach.','المنطقة التاريخية 3: القرب المباشر من جزء مكشوف تحت جهد عالٍ. لا يشكل العرض إذناً للمبتدئ بالاقتراب.'),
  T('Zone 4 historique : voisinage en basse tension dans l’ancien classement. La prévention actuelle privilégie le travail hors tension avec les mesures de consignation adaptées.','Historical zone 4: low-voltage proximity in the old classification. Current prevention prioritises de-energised work with appropriate isolation measures.','المنطقة التاريخية 4: جوار الجهد المنخفض في التصنيف القديم. تعطي الوقاية الحالية الأولوية للعمل دون جهد مع إجراءات العزل الملائمة.')];return {controls:`<div class="sim-parts">${descriptions.map((_,i)=>button('zone'+(i+1),T('Zone','Zone','المنطقة')+' '+(i+1),`aria-pressed="${i===0}"`)).join('')}</div>`,explain:T('Vue historique du guide 2004–2005, sans échelle. La numérotation, les distances et les habilitations ont évolué : ce dessin n’est pas un calculateur de distance de sécurité ni une formation habilitante.','Historical 2004–2005 guide view, not to scale. Zone numbering, distances and authorisation rules have evolved: this drawing is not a safety-distance calculator or qualification course.','عرض تاريخي من دليل 2004–2005، دون مقياس. تطورت أرقام المناطق والمسافات وقواعد التأهيل؛ الرسم ليس حاسبة لمسافة الأمان ولا تدريباً يمنح تأهيلاً.'),action:a=>{if(a.startsWith('zone'))selected=Number(a.slice(4));},update:()=>{ctx.host.querySelectorAll('[data-action^=zone]').forEach((b,i)=>b.setAttribute('aria-pressed',String(i+1===selected)));return svg(`<rect x="35" y="35" width="450" height="195" rx="12" class="${selected===1?'selected':'part'}"/><rect x="85" y="65" width="210" height="135" rx="10" class="${selected===2?'selected':'part'}"/><rect x="140" y="90" width="100" height="85" rx="8" class="${selected===3?'selected':'part'}"/><rect x="350" y="90" width="95" height="85" rx="8" class="${selected===4?'selected':'part'}"/>${text(62,60,'1')}${text(110,90,'2')}${text(190,127,'3 · HT')}${text(398,127,'4 · BT')}<path stroke="var(--danger-text)" d="M190 140l-10 15h15l-8 13M398 140l-10 15h15l-8 13"/>`,T('Classement historique des zones, sans échelle','Historical zone classification, not to scale','تصنيف تاريخي للمناطق دون مقياس'))+`<div class="sim-explanation"><h3>${T('Zone','Zone','المنطقة')} ${selected}</h3><p>${E(descriptions[selected-1])}</p><a href="https://www.inrs.fr/risques/electriques/prevention-risque-electrique.html" target="_blank" rel="noopener noreferrer">${T('Prévention actuelle · INRS','Current prevention guidance · INRS','إرشادات الوقاية الحالية · INRS')}</a></div>`;}};
 }
 const builders={wire:numeric,generator:numeric,active:numeric,rlc:numeric,loads:numeric,compensation:numeric,three:numeric,transformer:numeric,resistor,rc,charge:rc,discharge:rc,delay,energy,solar:explorer,'dc-motor':explorer,'ac-motor':explorer,air:explorer,frl:explorer,'relay-parts':explorer,cylinder,pilot,pilot2:pilot,heating,overload:protection,contactor:protection,cam,'thermal-curve':curves,'magnetic-curve':curves,zones};
 for(const name of ['simple','socket','double','two-way','switched-socket','latching','staircase','relay-wiring','central','timer'])builders[name]=lighting;
 function mount(host,lesson,options={}){const type=registry[lesson.id];if(!type)return false;const q=id=>host.querySelector('#sim-'+id),ctx={host,q,val:id=>q(id).value,get:id=>{const el=q(id),raw=el?.value;if(raw===undefined||!raw.trim())throw Error('empty');const n=N(raw);if(!Number.isFinite(n)||n<Number(el.dataset.min??-Infinity)||n>Number(el.dataset.max??Infinity))throw Error('range');return n;}};const model=builders[type](ctx,type);
  host.innerHTML=`<section class="native-sim" data-no-translate data-sim-type="${type}"><header class="sim-heading"><div><span class="badge blue">${T('Atelier interactif','Interactive workshop','ورشة تفاعلية')}</span><h2>${E(lesson.title)}</h2><p>${T('Modifiez les commandes et observez le résultat.','Change controls and observe the result.','غيّر أدوات التحكم ولاحظ النتيجة.')}</p></div><div class="sim-tools">${button('restart',T('Recommencer','Reset','إعادة البدء'))}${options.original&&!replacements.has(type)?button('original',T('Ouvrir l’original Flash','Open original Flash','فتح Flash الأصلي')):''}</div></header>${replacements.has(type)?status(T('Alternative pédagogique · fichier d’origine illisible','Educational alternative · original file unreadable','بديل تعليمي · الملف الأصلي غير قابل للقراءة')):''}<div class="sim-grid"><div class="sim-controls">${model.controls}</div><div class="sim-results"><div class="sim-error" role="status" aria-live="polite"></div><div class="sim-output"></div><div class="sim-model-note">${note(model.explain)}</div></div></div></section>`;
  const output=host.querySelector('.sim-output'),error=host.querySelector('.sim-error');
  const fail=()=>{output.hidden=true;error.textContent=T('Vérifiez les valeurs : tous les champs doivent être numériques et dans leurs limites. Les résistances, capacités, rendements et dimensions utilisés comme diviseurs doivent être positifs.','Check the values: every field must contain a number within its limits. Resistances, capacitances, efficiencies and dimensions used as divisors must be positive.','تحقق من القيم: يجب أن يكون كل حقل رقماً ضمن حدوده. يجب أن تكون المقاومات والسعات والمردود والأبعاد المستخدمة كمقامات موجبة.');};
  const update=()=>{try{output.innerHTML=model.update();output.hidden=false;error.textContent='';host.querySelectorAll('input[type=range]').forEach(el=>{const o=q('value-'+el.dataset.number);if(o)o.textContent=F(N(el.value));});}catch(e){fail();}};
  const changed=e=>{if(!e.target.matches('input,select'))return;try{model.change?.(e.target);update();}catch{fail();}};
  host.oninput=changed;host.onchange=changed;host.onclick=e=>{const b=e.target.closest('[data-action]');if(!b||!host.contains(b))return;const a=b.dataset.action;if(a==='restart'){mount(host,lesson,options);return;}if(a==='original'){host.oninput=host.onchange=host.onclick=null;options.original?.();return;}try{model.action?.(a);update();}catch{fail();}};update();return true;
 }
 function directory(lessons){return `<div data-no-translate><div class="page-header"><div><div class="eyebrow">${T('SIMULATIONS','SIMULATIONS','المحاكاة')}</div><h1>${T('Les ateliers du guide','Guide workshops','ورشات الدليل')}</h1><p>${T('41 activités reconstruites pour le tactile et les deux thèmes. Les 7 laboratoires complémentaires sont également disponibles.','41 activities rebuilt for touch and both themes. Seven complementary laboratories are also available.','41 نشاطاً أُعيد بناؤها للمس والوضعين البصريين. تتوفر أيضاً 7 مختبرات إضافية.')}</p></div><a href="#/lab" class="button">${T('Laboratoires complémentaires','Additional laboratories','المختبرات الإضافية')}</a></div><div class="sim-directory">${lessons.filter(l=>registry[l.id]).map(l=>`<a href="#/lesson/${encodeURIComponent(l.id)}?tab=activity"><strong>${E(l.title)}</strong><small>${E(l.description)}</small></a>`).join('')}</div></div>`;}
 window.GuideLegacy=Object.freeze({supports:lesson=>!!registry[typeof lesson==='string'?lesson:lesson.id],mount,directory,registry:Object.freeze(registry)});
})();
